from ukgen import *

STY = {
 'науковий': ['Фотосинтез — процес перетворення світлової енергії на хімічну.', 'Атом складається з ядра й електронної оболонки.', 'Дифузія — взаємне проникнення молекул однієї речовини між молекулами іншої.', 'Хімічний елемент — вид атомів з однаковим зарядом ядра.', 'Функція називається неперервною, якщо вона неперервна в кожній точці області.'],
 'публіцистичний': ['Сьогодні вся країна має стати на захист рідної мови!', 'Чи готові ми віддати майбутнє дітей байдужості?', 'Екологічна криза вимагає негайних дій кожного з нас.', 'Доки ми мовчимо, проблеми тільки ростуть.', 'Наше місто заслуговує на чисті вулиці та уважних господарів.'],
 'офіційно-діловий': ['Прошу надати мені відпустку з 1 липня 2026 року.', 'Наказую: призначити Іваненка П. І. відповідальним за проведення заходу.', 'Директор школи зобов’язаний забезпечити виконання цього наказу.', 'Цим підтверджую, що Коваль О. М. працює в установі з 2019 року.', 'Протокол засідання педагогічної ради № 5.'],
 'розмовний': ['Слухай, я сьогодні геть не встигаю, передзвоню пізніше!', 'Ну що ти, дурнички, не переймайся!', 'Привіт! Як діла? Шось давно не бачились.', 'Завтра зустрінемось біля кав’ярні, добре?', 'Та я вже стільки разів казав, а він усе одно не слухає!'],
 'художній': ['Місяць срібним човником плив по небу, і тихо шепотіли верби.', 'Осінь пензлем золотим розмалювала ліс.', 'Вітер тулився до віконниці, мов зляканий кіт.', 'Над річкою стелився молочний туман, і день народжувався повільно та урочисто.', 'Степ лежав безкраїй, мов застигле море.'],
}
STF = {
 'науковий': ['наявність термінів', 'точність і логічність викладу', 'абстрактна лексика й узагальненість'],
 'публіцистичний': ['риторичні запитання й заклики', 'виражена оцінність і полемічність', 'поєднання інформації із впливом на читача'],
 'офіційно-діловий': ['стандартизовані звороти (канцеляризми)', 'сувора форма документа', 'шаблонні мовні формули'],
 'розмовний': ['вигуки та частки', 'неповні речення', 'усна форма й непідготовленість'],
 'художній': ['образність, метафори й епітети', 'використання художніх засобів', 'індивідуальність авторської мови'],
}
GEN = {
 'науковий': ['стаття в наукому журналі', 'реферат', 'підручник', 'анотація до монографії', 'наукова доповідь'],
 'публіцистичний': ['репортаж', 'нарис', 'фейлетон', 'памфлет', 'інтерв’ю в газеті'],
 'офіційно-діловий': ['заява', 'наказ', 'протокол', 'автобіографія', 'розписка', 'довідка', 'характеристика'],
 'розмовний': ['дружня бесіда', 'розмова за столом', 'телефонна розмова з другом', 'побутовий діалог'],
 'художній': ['роман', 'оповідання', 'поема', 'новела', 'байка', 'казка'],
}
GEN['науковий'][0] = 'стаття в науковому журналі'
GI={'науковий':'наукового','публіцистичний':'публіцистичного','офіційно-діловий':'офіційно-ділового','розмовний':'розмовного','художній':'художнього'}
LO={'науковий':'науковому','публіцистичний':'публіцистичному','офіційно-діловий':'офіційно-діловому','розмовний':'розмовному','художній':'художньому'}
def others(d, k, n, rng): return rng.sample([x for x in d if x != k], n)
def f_style_sample(T, rng, lv):
    k = rng.choice(list(STY)); s = rng.choice(STY[k])
    k2 = others(STY, k, 4 if lv == 3 else 3, rng)
    return T.add(lv, f'Який стиль мови представлено в тексті: «{s}»?', k, [(x, f'для {GI[x]} стилю властиве: {STF[x][0]}, а в тексті — {STF[k][0]}') for x in k2], 'стиль визначай за метою й ознаками, а не за окремим словом', f'у тексті виявлено ознаки {GI[k]} стилю: {STF[k][0]}')
def f_style_feat(T, rng, lv):
    k = rng.choice(list(STF)); f = rng.choice(STF[k])
    ws = []
    for x in others(STF, k, 3, rng): ws.append((rng.choice(STF[x]), f'це ознака {x} стилю'))
    return T.add(lv, f'Для якого стилю мови характерна така ознака: {f}?', k, [(x, f'для {GI[x]} стилю характерні інші ознаки: {STF[x][0]}') for x in others(STF, k, 3, rng)], 'ознаки стилів не перетинаються у ключових рисах', f'{f} — ознака {GI[k]} стилю')
def f_feat_of(T, rng, lv):
    k = rng.choice(list(STF)); f = rng.choice(STF[k])
    ws = [(rng.choice(STF[x]), f'це ознака {GI[x]} стилю, а не {GI[k]}') for x in others(STF, k, 3, rng)]
    return T.add(lv, f'Яка ознака характерна для {GI[k]} стилю мови?', f, ws, 'не плутай ознаки сусідніх стилів', f'для {GI[k]} стилю характерне: {f}')
def f_genre(T, rng, lv):
    k = rng.choice(list(GEN)); g = rng.choice(GEN[k])
    return T.add(lv, f'До якого стилю належить жанр «{g}»?', k, [(x, f'у {LO[x]} стилі функціонують інші жанри: {GEN[x][0]}') for x in others(GEN, k, 3, rng)], 'жанр визначає стиль', f'жанр «{g}» належить до {GI[k]} стилю')
def f_genre_of(T, rng, lv):
    k = rng.choice(list(GEN)); g = rng.choice(GEN[k])
    ws = [(rng.choice(GEN[x]), f'це жанр {GI[x]} стилю') for x in others(GEN, k, 3, rng)]
    return T.add(lv, f'Який жанр належить до {GI[k]} стилю?', g, ws, 'спочатку визнач стиль, потім шукай жанр', f'«{g}» — жанр {GI[k]} стилю')

TRD = {'епітет': 'художнє означення, що увиразнює предмет чи явище', 'метафора': 'перенесення властивостей одного явища на інше за подібністю', 'порівняння': 'зіставлення двох явищ за допомогою слів мов, наче, як', 'гіпербола': 'художнє перебільшення', 'літота': 'художнє применшення', 'персоніфікація': 'наділення неживих предметів рисами живих істот', 'оксиморон': 'поєднання слів із протилежним значенням', 'перифраза': 'заміна назви описовим зворотом', 'анафора': 'повтор початкових слів у суміжних реченнях чи рядках', 'риторичне запитання': 'запитання, що не потребує відповіді'}
TRE = {'епітет': ['У квітучому саду співали птахи.', 'Тихий вечір опустився на село.'], 'метафора': ['Золото осені вкрило парк.', 'Сніг укрив поле білою ковдрою.'], 'порівняння': ['Білий, мов сніг, лебідь плив річкою.', 'Очі, наче зорі, світилися в темряві.'], 'гіпербола': ['Від його крику тремтіли гори.', 'Я тобі сто разів казав!'], 'літота': ['Ваш шпіц — завбільшки з наперсток.', 'Він ходить тихіше води, нижче трави.'], 'персоніфікація': ['Вітер грається листям.', 'Ліс шепоче свої таємниці.'], 'оксиморон': ['Над полем стояла гучна тиша.', 'Він відчував солодкий біль розлуки.'], 'перифраза': ['Цар звірів ліниво зажмурився на сонці.', 'Автор «Кобзаря» — гордість України.'], 'анафора': ['Люблю тебе в ранковій тиші, люблю тебе в шумі дощу, люблю тебе в кожній миті.', 'Скажи мені правду, скажи мені відверто, скажи мені все до кінця.'], 'риторичне запитання': ['Хто ж не мріє про щастя?', 'Чи довго ми ще терпітимо байдужість?']}
def tr_others(k, n, rng):
    ex = {'метафора': ['персоніфікація'], 'персоніфікація': ['метафора']}.get(k, [])
    return rng.sample([x for x in TRD if x != k and x not in ex], n)
def f_trope_ex(T, rng, lv):
    k = rng.choice(list(TRE)); s = rng.choice(TRE[k])
    return T.add(lv, f'Який художній засіб використано в реченні «{s}»?', k, [(x, f'це {TRD[x]}; у реченні цього немає') for x in tr_others(k, 4 if lv == 3 else 3, rng)], 'шукай ключову ознаку засобу', f'у реченні — {k}: це {TRD[k]}')
def f_trope_def(T, rng, lv):
    k = rng.choice(list(TRD))
    return T.add(lv, f'Що таке {k}?', TRD[k], [(TRD[x], f'це означення поняття «{x}»') for x in tr_others(k, 3, rng)], 'не плутай схожі засоби', f'{k} — {TRD[k]}')
def f_trope_rev(T, rng, lv):
    k = rng.choice(list(TRD))
    return T.add(lv, f'Як називається засіб: {TRD[k]}?', k, [(x, f'це {TRD[x]}') for x in tr_others(k, 3, rng)], 'співвідноси ознаку з назвою', f'{TRD[k]} — {k}')

SP = {'розповідь': ['Вранці ми вирушили в дорогу, потім зупинилися біля річки, а ввечері повернулися додому.', 'Спочатку хлопець упав, потім підвівся, обтрусився і пішов далі.', 'Наступного дня дощ перестав, і мандрівники знову рушили вгору стежкою.'],
      'опис': ['Будинок стояв край села: низький, білий, з зеленими віконницями та старою липою біля ґанку.', 'Кімната була невеличка, світла, з письмовим столом біля вікна й полицею книжок на стіні.', 'Озеро лежало тихе, прозоре, обрамлене темним лісом.'],
      'роздум': ['Чи можна вважати людину вільною, якщо вона залежить від чужої думки? Адже свобода — це передусім відповідальність.', 'Книжка вчить мислити, бо читач мусить порівнювати, аналізувати й робити висновки.', 'Дружба потребує щирості, тому що без довіри вона перетворюється на звичку.']}
SPD = {'розповідь': 'повідомляє про послідовність подій', 'опис': 'змальовує ознаки предмета чи явища', 'роздум': 'доводить думку, пояснює причини та наслідки'}
def f_speech(T, rng, lv):
    k = rng.choice(list(SP)); s = rng.choice(SP[k])
    return T.add(lv, f'Укажіть тип мовлення: «{s}»', k, [(x, f'це текст, що {SPD[x]}, а тут — {SPD[k]}') for x in SP if x != k] + [('діалог', 'у тексті одна мовна лінія без реплік')], 'тип мовлення визначає мета висловлювання', f'текст {SPD[k]} — це {k}')

PL = [('моя автобіографія', 'автобіографія'), ('вільна вакансія', 'вакансія'), ('прейскурант цін', 'прейскурант'), ('пам’ятний сувенір', 'сувенір'), ('монументальний пам’ятник', 'пам’ятник'), ('основний фундамент', 'фундамент'), ('моя біографія', 'біографія')]
PL = [p for p in PL if p[0] != 'моя біографія']
NEU = ['вільний час', 'прямий шлях', 'швидкий потяг', 'новий підручник', 'цікава історія', 'старе місто', 'складний вибір']
def f_pleo(T, rng, lv):
    b, g = rng.choice(PL)
    return T.add(lv, 'У якому словосполученні є плеоназм?', b, [(n, 'мовної помилки немає') for n in rng.sample(NEU, 3)], 'плеоназм — зайві слова з однаковим значенням', f'«{b}» — плеоназм; слово повторює значення: правильно «{g}»')
RU = [('приймати участь', 'брати участь'), ('слідуючий', 'наступний'), ('на протязі дня', 'протягом дня'), ('міроприємство', 'захід'), ('співпадати', 'збігатися'), ('получити', 'отримати'), ('вірна відповідь', 'правильна відповідь')]
def f_ru(T, rng, lv):
    (b, g), (b2, g2), (b3, g3), (b4, g4) = rng.sample(RU, 4)
    return T.add(lv, 'Укажіть нормативне словосполучення.', g, [(b, f'калька з російської; правильно «{g}»'), (b2, f'русизм; правильно «{g2}»'), (b3, f'русизм; правильно «{g3}»')], 'при мовних кальках перевіряй літературну форму', f'«{g}» — літературна норма')
def f_ru_bad(T, rng, lv):
    (b, g), (b2, g2), (b3, g3), (b4, g4) = rng.sample(RU, 4)
    return T.add(lv, 'Укажіть словосполучення з мовною помилкою (калька).', b, [(g2, 'літературна норма'), (g3, 'літературна норма'), (g4, 'літературна норма')], 'калька — дослівний переклад з російської', f'«{b}» — калька; правильно «{g}»')

DOC = {'заява': 'документ-прохання особи до установи чи посадової особи', 'автобіографія': 'розповідь про власне життя, написана від першої особи', 'резюме': 'стислий виклад відомостей про освіту та досвід для працевлаштування', 'протокол': 'документ, що фіксує хід і рішення зборів чи засідання', 'довідка': 'документ, що підтверджує певний факт чи подію', 'розписка': 'документ, що підтверджує отримання грошей чи речей', 'характеристика': 'документ з оцінкою ділових і особистих якостей особи', 'наказ': 'розпорядчий документ керівника', 'доручення': 'документ, яким одна особа уповноважує іншу діяти від її імені'}
def f_doc(T, rng, lv):
    k = rng.choice(list(DOC)); ws = rng.sample([x for x in DOC if x != k], 3)
    return T.add(lv, f'Що таке {k}?', DOC[k], [(DOC[x], f'це означення документа «{x}»') for x in ws], 'документи відрізняються метою', f'{k} — {DOC[k]}')
def f_doc_rev(T, rng, lv):
    k = rng.choice(list(DOC)); ws = rng.sample([x for x in DOC if x != k], 3)
    return T.add(lv, f'Як називається документ: {DOC[k]}?', k, [(x, f'це {DOC[x]}') for x in ws], 'співвідноси мету з назвою', f'{DOC[k]} — {k}')
ZAV = ['адресат (кому)', 'відомості про автора (від кого)', 'назва документа', 'текст прохання', 'дата', 'підпис']
BAD = ['номер протоколу', 'печатка організації-адресата', 'перелік свідків', 'рішення комісії']
def f_zav(T, rng, lv):
    return T.add(lv, 'Який реквізит НЕ є обов’язковим у заяві?', rng.choice(BAD), [(r, 'це обов’язковий реквізит заяви') for r in rng.sample(ZAV, 3)], 'у заяві ключове — прохання', 'у заяві зазвичай немає цього реквізиту')

CONN = {'ланцюговий': ['У селі стояла стара хата. Хата ця пам’ятала багато поколінь. Покоління змінювалися, а двері завжди були відчинені.', 'Над рікою піднявся туман. Туман вкрив луки. Луки зникли в білій імлі.'],
        'паралельний': ['Сонце сходить. Птахи співають. Квіти розпускаються.', 'Ми прийшли до лісу. Ми зупинилися біля струмка. Ми розпалили багаття.']}
CD = {'ланцюговий': 'кожне наступне речення повторює слово з кінця попереднього', 'паралельний': 'речення мають однакову будову та починаються схоже'}
def f_conn(T, rng, lv):
    k = rng.choice(list(CONN)); s = rng.choice(CONN[k]); o = [x for x in CONN if x != k][0]
    return T.add(lv, f'Який зв’язок між реченнями в тексті: «{s}»?', k, [(o, f'{o}: {CD[o]}; тут інакше'), ('приєднувальний', 'у тексті немає приєднувальних конструкцій'), ('безпосередній', 'у цьому тексті виражений ланцюговий чи паралельний зв’язок')] if False else [(o, f'{o}: {CD[o]}, а тут {CD[k]}'), ('сурядний', 'це вид зв’язку у складному реченні, а не між реченнями тексту'), ('підрядний', 'це вид зв’язку у складному реченні, а не між реченнями тексту')], 'зв’язок між реченнями — тип тексту', f'{k}: {CD[k]}')

H = []
def h(lv, text, ans, wrongs, trap, sol): H.append((lv, text, ans, wrongs, trap, sol))
h(1, 'Скільки функціональних стилів виділяють в українській мові?', '5 (науковий, публіцистичний, офіційно-діловий, розмовний, художній)', [('3', 'трьох стилів недостатньо'), ('4', 'пропущено один стиль'), ('6', 'у шкільному курсі виділяють п’ять')], 'питання про основні стилі', 'п’ять основних стилів')
h(1, 'Що таке тема тексту?', 'те, про що йдеться в тексті', [('головна думка автора', 'це ідея, а не тема'), ('перше речення', 'це не завжди тема'), ('кількість абзаців', 'кількість абзаців не є темою')], 'тема ≠ ідея', 'тема — про що текст')
